import { describe, expect, it } from "vitest";
import { buildRoomPlaylist } from "@/components/community-room-thread";

describe("buildRoomPlaylist", () => {
	const playlist = buildRoomPlaylist("Daily digest line");

	it("inserts the bot message once, after the fifth chat bubble", () => {
		const bots = playlist.filter((b) => b.kind === "bot");
		expect(bots).toHaveLength(1);
		expect(playlist.findIndex((b) => b.kind === "bot")).toBe(5);
		expect(bots[0].text).toBe("Daily digest line");
	});

	it("keeps timestamps in order, so the bot never posts before the message above it", () => {
		// The bot read 08:01 under an 11:42 message (visual audit, 2026-09-25).
		const times = playlist.map((b) => b.time);
		expect(times).toEqual([...times].sort());
	});

	it("gives every bubble a unique id", () => {
		expect(new Set(playlist.map((b) => b.id)).size).toBe(playlist.length);
	});
});
